    "res_bc_anke.1": { en: "Did you know? The moon pulls on the sea. That makes the tides.", t: [["Weißt", "", "do you know", "wissen"], ["du", "", "you"], ["?", "", ""], ["Der", "", "the"], ["Mond", "", "moon"], ["zieht", "", "pulls", "ziehen"], ["am", "", "on the", "an"], ["Meer", "", "sea"], [".", "", ""], ["So", "", "so", "so"], ["entstehen", "", "come about"], ["Ebbe", "", "low tide"], ["und", "", "and"], ["Flut", "", "high tide"], [".", "", ""]] },
    "res_bc_anke.2": { en: "Twice a day the water comes, twice a day it goes. Every day about fifty minutes later.", t: [["Zweimal", "", "twice", "zweimal"], ["am", "", "a", "an"], ["Tag", "", "day"], ["kommt", "", "comes", "kommen"], ["das", "", "the", "der"], ["Wasser", "", "water"], [",", "", ""], ["zweimal", "", "twice"], ["am", "", "a", "an"], ["Tag", "", "day"], ["geht", "", "goes", "gehen"], ["es", "", "it"], [".", "", ""], ["Jeden", "", "every", "jeder"], ["Tag", "", "day"], ["etwa", "", "about"], ["fünfzig", "", "fifty"], ["Minuten", "", "minutes", "Minute"], ["später", "", "later", "spät"], [".", "", ""]] },
    "res_bc_anke.3": { en: "At full moon the tides are especially high.", t: [["Bei", "", "at"], ["Vollmond", "", "full moon"], ["ist", "", "is", "sein"], ["die", "", "the", "der"], ["Flut", "", "high tide"], ["besonders", "", "especially"], ["hoch", "", "high"], [".", "", ""]] },
    "res_bc_wilhelm.1": { en: "I was born on this beach, eighty years ago.", t: [["Ich", "", "I", "ich"], ["bin", "", "was", "sein"], ["an", "", "on"], ["diesem", "", "this", "dieser"], ["Strand", "", "beach"], ["geboren", "", "born", "gebären"], [",", "", ""], ["vor", "", "ago"], ["achtzig", "", "eighty"], ["Jahren", "", "years", "Jahr"], [".", "", ""]] },
    "res_bc_wilhelm.2": { en: "Sea turtles swim thousands of kilometres. But to lay their eggs, they come back to the beach where they were born.", t: [["Meeresschildkröten", "", "sea turtles", "Meeresschildkröte"], ["schwimmen", "", "swim"], ["tausende", "", "thousands", "tausend"], ["Kilometer", "", "kilometres"], [".", "", ""], ["Aber", "", "but", "aber"], ["für", "", "for"], ["die", "", "the", "der"], ["Eier", "", "eggs", "Ei"], ["kommen", "", "come"], ["sie", "", "they"], ["an", "", "to"], ["ihren", "", "their", "ihr"], ["Strand", "", "beach"], ["zurück", "", "back"], [".", "", ""]] },
    "res_bc_wilhelm.3": { en: "Please don't put lights on the beach at night. The little turtles go to the brightest light: that should be the sea.", t: [["Bitte", "", "please", "bitte"], ["kein", "", "no"], ["Licht", "", "light"], ["nachts", "", "at night"], ["am", "", "on the", "an"], ["Strand", "", "beach"], ["!", "", ""], ["Die", "", "the", "der"], ["kleinen", "", "little", "klein"], ["Schildkröten", "", "turtles", "Schildkröte"], ["laufen", "", "run"], ["zum", "", "to the", "zu"], ["Licht", "", "light"], [":", "", ""], ["Das", "", "that", "das"], ["soll", "", "should", "sollen"], ["das", "", "the", "der"], ["Meer", "", "sea"], ["sein", "", "be"], [".", "", ""]] },
    "res_bc_rosa.1": { en: "Welcome to my café! Try a glass of water... but not from the sea!", t: [["Willkommen", "", "welcome", "willkommen"], ["in", "", "in"], ["meinem", "", "my", "mein"], ["Café", "", "café"], ["!", "", ""], ["Trink", "", "drink", "trinken"], ["ein", "", "a"], ["Glas", "", "glass"], ["Wasser", "", "water"], ["...", "", ""], ["aber", "", "but"], ["nicht", "", "not"], ["aus", "", "from"], ["dem", "", "the", "der"], ["Meer", "", "sea"], ["!", "", ""]] },
    "res_bc_rosa.2": { en: "Why is the sea salty? Rivers carry a little salt from the rocks to the sea. The sun takes the water, but the salt stays.", t: [["Warum", "", "why", "warum"], ["ist", "", "is", "sein"], ["das", "", "the", "der"], ["Meer", "", "sea"], ["salzig", "", "salty"], ["?", "", ""], ["Flüsse", "", "rivers", "Fluss"], ["bringen", "", "carry"], ["etwas", "", "some"], ["Salz", "", "salt"], ["von", "", "from"], ["den", "", "the", "der"], ["Steinen", "", "rocks", "Stein"], ["ins", "", "into the", "in"], ["Meer", "", "sea"], [".", "", ""], ["Die", "", "the", "der"], ["Sonne", "", "sun"], ["nimmt", "", "takes", "nehmen"], ["das", "", "the", "der"], ["Wasser", "", "water"], [",", "", ""], ["das", "", "the", "der"], ["Salz", "", "salt"], ["bleibt", "", "stays", "bleiben"], [".", "", ""]] },
    "res_bc_rosa.3": { en: "Millions of years of rivers: that's a lot of salt!", t: [["Millionen", "", "millions", "Million"], ["Jahre", "", "years", "Jahr"], ["Flüsse", "", "rivers", "Fluss"], [":", "", ""], ["Das", "", "that", "das"], ["ist", "", "is", "sein"], ["viel", "", "a lot of"], ["Salz", "", "salt"], ["!", "", ""]] },
