    "res_bc_konrad.2": { en: "Water swallows red light, but the blue light comes back. That's why the deep sea looks blue.", t: [["Wasser", "", "water"], ["schluckt", "", "swallows", "schlucken"], ["das", "", "the", "der"], ["rote", "", "red", "rot"], ["Licht", "", "light"], [",", "", ""], ["aber", "", "but"], ["das", "", "the", "der"], ["blaue", "", "blue", "blau"], ["Licht", "", "light"], ["kommt", "", "comes", "kommen"], ["zurück", "", "back"], [".", "", ""], ["Darum", "", "that's why", "darum"], ["sieht", "", "looks", "aussehen"], ["tiefes", "", "deep", "tief"], ["Wasser", "", "water"], ["blau", "", "blue"], ["aus", "", "(sieht aus: looks)", "aussehen"], [".", "", ""]] },
    "res_bc_konrad.3": { en: "Over white sand the water is turquoise. Beautiful, isn't it?", t: [["Über", "", "over", "über"], ["weißem", "", "white", "weiß"], ["Sand", "", "sand"], ["ist", "", "is", "sein"], ["das", "", "the", "der"], ["Wasser", "", "water"], ["türkis", "", "turquoise"], [".", "", ""], ["Schön", "", "beautiful", "schön"], [",", "", ""], ["oder", "", "isn't it"], ["?", "", ""]] },
    "res_bc_hinrich.1": { en: "I was a sailor for forty years. Here is my old ship's wheel.", t: [["Ich", "", "I", "ich"], ["war", "", "was", "sein"], ["vierzig", "", "forty"], ["Jahre", "", "years", "Jahr"], ["Seemann", "", "sailor"], [".", "", ""], ["Hier", "", "here", "hier"], ["ist", "", "is", "sein"], ["mein", "", "my"], ["altes", "", "old", "alt"], ["Steuerrad", "", "ship's wheel"], [".", "", ""]] },
