    "res_bc_erna.2": { en: "Can you hear the sea? People say so. But it's really the sound of the room in the shell.", t: [["Hörst", "", "do you hear", "hören"], ["du", "", "you"], ["das", "", "the", "der"], ["Meer", "", "sea"], ["?", "", ""], ["Das", "", "that", "das"], ["sagen", "", "say"], ["die", "", "the", "der"], ["Leute", "", "people"], [".", "", ""], ["Aber", "", "but", "aber"], ["es", "", "it"], ["ist", "", "is", "sein"], ["das", "", "the", "der"], ["Geräusch", "", "sound"], ["vom", "", "of the", "von"], ["Zimmer", "", "room"], ["in", "", "in"], ["der", "", "the"], ["Muschel", "", "shell"], [".", "", ""]] },
    "res_bc_erna.3": { en: "It still sounds lovely, doesn't it? Have a cookie!", t: [["Es", "", "it", "es"], ["klingt", "", "sounds", "klingen"], ["trotzdem", "", "still"], ["schön", "", "lovely"], [",", "", ""], ["oder", "", "doesn't it"], ["?", "", ""], ["Nimm", "", "have", "nehmen"], ["einen", "", "a", "ein"], ["Keks", "", "cookie"], ["!", "", ""]] },
