    "res_bc_finn.2": { en: "They travel a long way. Near the beach the water gets shallow, so the wave gets high and breaks.", t: [["Sie", "", "they", "sie"], ["reisen", "", "travel"], ["sehr", "", "very"], ["weit", "", "far"], [".", "", ""], ["Am", "", "at the", "an"], ["Strand", "", "beach"], ["ist", "", "is", "sein"], ["das", "", "the", "der"], ["Wasser", "", "water"], ["flach", "", "shallow"], [",", "", ""], ["dann", "", "then"], ["wird", "", "becomes", "werden"], ["die", "", "the", "der"], ["Welle", "", "wave"], ["hoch", "", "high"], ["und", "", "and"], ["bricht", "", "breaks", "brechen"], [".", "", ""]] },
    "res_bc_finn.3": { en: "The best waves come in the morning. See you on the water!", t: [["Die", "", "the", "der"], ["besten", "", "best", "gut"], ["Wellen", "", "waves", "Welle"], ["kommen", "", "come"], ["am", "", "in the", "an"], ["Morgen", "", "morning"], [".", "", ""], ["Bis", "", "until", "bis"], ["dann", "", "then"], ["auf", "", "on"], ["dem", "", "the", "der"], ["Wasser", "", "water"], ["!", "", ""]] },
    "res_bc_meike.1": { en: "I study the reef. Do you know that coral is an animal?", t: [["Ich", "", "I", "ich"], ["erforsche", "", "study", "erforschen"], ["das", "", "the", "der"], ["Riff", "", "reef"], [".", "", ""], ["Weißt", "", "do you know", "wissen"], ["du", "", "you"], [",", "", ""], ["dass", "", "that"], ["Korallen", "", "corals", "Koralle"], ["Tiere", "", "animals", "Tier"], ["sind", "", "are", "sein"], ["?", "", ""]] },
    "res_bc_meike.2": { en: "Tiny animals build a house of stone. A reef grows only one or two centimetres a year.", t: [["Winzige", "", "tiny", "winzig"], ["Tiere", "", "animals", "Tier"], ["bauen", "", "build"], ["ein", "", "a"], ["Haus", "", "house"], ["aus", "", "of"], ["Stein", "", "stone"], [".", "", ""], ["Ein", "", "a"], ["Riff", "", "reef"], ["wächst", "", "grows", "wachsen"], ["nur", "", "only"], ["ein", "", "one"], ["bis", "", "to"], ["zwei", "", "two"], ["Zentimeter", "", "centimetres"], ["im", "", "a", "in"], ["Jahr", "", "year"], [".", "", ""]] },
    "res_bc_meike.3": { en: "So please don't touch the coral!", t: [["Also", "", "so", "also"], ["bitte", "", "please"], ["nicht", "", "not"], ["die", "", "the", "der"], ["Korallen", "", "corals", "Koralle"], ["anfassen", "", "touch"], ["!", "", ""]] },
