    "res_bc_jan.2": { en: "Did you know? Dolphins sleep with only half their brain. The other half watches.", t: [["Weißt", "", "do you know", "wissen"], ["du", "", "you"], ["?", "", ""], ["Delfine", "", "dolphins", "Delfin"], ["schlafen", "", "sleep"], ["nur", "", "only"], ["mit", "", "with"], ["einer", "", "one", "ein"], ["Hälfte", "", "half"], ["vom", "", "of the", "von"], ["Gehirn", "", "brain"], [".", "", ""], ["Die", "", "the", "der"], ["andere", "", "other", "anderer"], ["Hälfte", "", "half"], ["passt", "", "watches", "aufpassen"], ["auf", "", "(passt auf: watches)", "aufpassen"], [".", "", ""]] },
